package net.officefloor.hq.app.person;

import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.Set;
import net.officefloor.hq.app.alias.Alias;
import net.officefloor.hq.app.alias.AliasRepository;
import net.officefloor.hq.app.sheet.Sheet;
import net.officefloor.plugin.variable.Val;
import net.officefloor.web.ObjectResponse;

public class RespondWithPeople {
    public void respond(@Val Sheet sheet, @Val List<Person> people, AliasRepository aliases, NameTree tree,
            ObjectResponse<List<PersonResponse>> response) {
        Set<String> taken = tree.taken(sheet.id());
        Map<Long, List<String>> byPerson = new HashMap<>();
        if (!taken.isEmpty()) {
            for (Alias a : aliases.findAll(sheet.id())) {
                byPerson.computeIfAbsent(a.personId(), (k) -> new java.util.ArrayList<>()).add(a.alias());
            }
        }
        response.send(people.stream().map((p) -> PersonResponse.from(p,
                NameTree.clashing(taken, p.name(), byPerson.getOrDefault(p.id(), List.of())))).toList());
    }
}
package net.officefloor.hq.app.person;

import net.officefloor.plugin.variable.Val;
import net.officefloor.web.ObjectResponse;

/** Responds with the person as they arrived on the other sheet. */
public class RespondWithTransfer {
    public void respond(@Val Transferred transferred, PersonRepository people, NameTree tree,
            ObjectResponse<PersonResponse> response) {
        Person person = transferred.person();
        response.send(PersonResponse.from(person, tree.clashing(person, people.aliases(person.sheetId(), person.id()))));
    }
}
import { PersonColumnHeads, PersonColumns } from '../../slots/defs/personColumns';
import { useCurrentSheet, useCurrentUser } from '../session/session';
import { PersonError } from './personError';
import { useEditingPerson, usePeople, useShowRetired } from './people';

// Every person on the sheet, in their order in the list (their positions), each with their name and grade and
// the columns features add (slots/defs/personColumns.ts). Retired people are left out unless the
// show-retired toggle is on.
export function PeopleList() {
  const [user] = useCurrentUser();
  const [sheet] = useCurrentSheet();
  const [, setEditing] = useEditingPerson();
  const people = usePeople();
  const [showRetired] = useShowRetired();

  if (!user || !sheet) return null;

  return (
    <table data-testid="people">
      <thead>
        <tr>
          <th>Name</th>
          <th>Grade</th>
          <th>Terms</th>
          <th>Contact</th>
          <th>Clashing</th>
          <PersonColumnHeads.Slot />
          <th />
        </tr>
      </thead>
      <tbody>
        {(people.data ?? []).filter((p) => showRetired || !p.retired).map((p) => (
          <tr key={p.id} data-testid={`person-row-${p.id}`}>
            <td data-testid="person-name" style={{ whiteSpace: 'pre' }}>
              {p.name}
            </td>
            <td data-testid="person-grade">{p.grade}</td>
            <td data-testid="person-terms">{p.terms ?? ''}</td>
            <td data-testid="person-contact">{p.contact ?? ''}</td>
            <td data-testid="person-clashing">{p.clashing ? 'yes' : 'no'}</td>
            <PersonColumns.Slot person={p} />
            <td>
              <button type="button" data-testid={`person-edit-${p.id}`} onClick={() => setEditing(p.id)}>
                Edit
              </button>
              <PersonError personId={p.id} />
            </td>
          </tr>
        ))}
      </tbody>
    </table>
  );
}
